package com.gamehub.admin;import com.gamehub.common.ApiResponse;import com.gamehub.tag.TagService;import com.gamehub.tag.dto.TagRequest;import com.gamehub.tag.entity.Tag;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/admin/tags") public class AdminTagController {private final TagService service;public AdminTagController(TagService service){this.service=service;}@GetMapping public ApiResponse<List<Tag>>list(@RequestParam(required=false)String q){return ApiResponse.ok(service.list(q));}@PostMapping public ApiResponse<Tag>create(@Valid @RequestBody TagRequest r){return ApiResponse.ok(service.save(null,r));}@PutMapping("/{id}")public ApiResponse<Tag>update(@PathVariable Long id,@Valid @RequestBody TagRequest r){return ApiResponse.ok(service.save(id,r));}@DeleteMapping("/{id}")public ApiResponse<Void>delete(@PathVariable Long id){service.delete(id);return ApiResponse.ok();}}
